postCreateCommand:
cd /workspace && npm install && cd engine && npm ci && if [ -f .env ]; then set -a && source .env && set +a; fi && mkdir -p /home/developer/.continue && cat > /home/developer/.continue/config.json << 'EOF'
{
  "models": [
    {
      "title": "OpenRouter GPT-4o-mini",
      "provider": "openrouter",
      "model": "openai/gpt-4o-mini",
      "apiKey": "env:OPENROUTER_API_KEY",
      "apiBase": "https://openrouter.ai/api/v1"
    }
  ],
  "tabAutocompleteModel": {
    "title": "OpenRouter GPT-4o-mini",
    "provider": "openrouter",
    "model": "openai/gpt-4o-mini",
    "apiKey": "env:OPENROUTER_API_KEY",
    "apiBase": "https://openrouter.ai/api/v1"
  }
}
EOF
&& echo 'Continue config setup complete'
